NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'II Corinthians'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, und Timotheus, der Bruder, an die Gemeinde Gottes in Korinth, samt allen Heiligen in ganz Achaja:',
        2: 'Gruß euch und Friede von Gott unserem Vater und Herrn Jesus Christus!',
        3: 'Gelobt sei Gott und der Vater unseres Herrn Jesus Christus, der Vater der Barmherzigkeit und der Gott allen Trostes,',
        4: 'Der uns tröstet in aller unserer Trübsal, so daß wir auch euch trösten können in aller Trübsal, mit dem Trost, womit wir selbst von Gott getröstet werden.',
        5: 'Denn gleichwie wir viel von Christus Leiden haben, also haben wir auch durch Christus des Trostes viel.',
        6: 'Haben wir aber Trübsal, so geschieht es zu eurem Trost und Heil; oder werden wir getröstet, so geschieht es auch zum Trost für euch, der sich wirksamer erweist in Ertragung derselben Leiden, die auch wir erleiden. Auch steht unsere Hoffnung fest euretwegen,',
        7: 'Weil wir wissen, daß ihr, wie der Leiden, so auch des Trostes teilhaftig seid.',
        8: 'Denn wir wollen euch nicht vorenthalten, Brüder, welche Trübsal uns in Asien widerfahren ist, daß wir über die Maßen und über Vermögen beschwert wurden, also, daß wir selbst am Leben verzweifelten;',
        9: 'Und hatten bei uns selbst das Todesurteil gesprochen, auf daß wir nicht auf uns selbst vertraueten, sondern auf den Gott, Der die Toten auferweckt.',
        10: 'Der uns von solchem Tode errettet hat und errettet; und wir haben auf Ihn die Hoffnung gesetzt, daß Er auch ferner uns erretten wird,',
        11: 'Indem auch ihr durch euer Gebet uns unterstützt, auf daß für die Gnadengabe, die uns durch vieler Gebet zuteil geworden ist, auch von vielen unsertwegen gedankt werde.',
        12: 'Denn das ist unser Ruhm, das Zeugnis unseres Gewissens, daß wir in Einfalt und gottgefälliger Lauterkeit',
        13: 'Denn wir schreiben euch nichts anderes, als was ihr leset und auch selbst erkennt, und wie ich hoffe, bis an das Ende erkennen werdet,',
        14: 'Wie ihr auch zum Teil schon erkannt habt, daß wir euer Ruhm sind, wie auch ihr der unsrige seid, auf den Tag des Herrn Jesus.',
        15: 'Und auf dieses Vertrauen hin wollte ich früher zu euch kommen, auf daß ihr abermals eine Wohltat empfinget,',
        16: 'Und von euch nach Mazedonien reisen, und wieder von Mazedonien aus zu euch kommen, und mich von euch nach Judäa geleiten lassen.',
        17: 'Habe ich, als ich diesen Vorsatz faßte, mich des Leichtsinns schuldig gemacht? oder fasse ich meine Vorsätze nach dem Fleisch, so daß das Ja oder Nein bei mir stünde?',
        18: 'Aber Gott ist getreu und so war mein Wort an euch nicht Ja und Nein;',
        19: 'Denn Gottes Sohn, Jesus Christus, Der unter euch durch uns gepredigt worden ist,',
        20: 'Denn so viele Verheißungen Gottes da sind, die sind in Ihm Ja, und in Ihm Amen, zur Verherrlichung Gottes durch uns.',
        21: 'Gott aber ist es, Der uns mit euch im Glauben an Jesus Christus befestigt und uns gesalbt hat;',
        22: 'Der uns besiegelt, und das Pfand des Geistes in unsere Herzen gegeben hat.',
        23: 'Ich rufe aber Gott zum Zeugen auf über meine Seele, daß ich euch schonen wollte, indem ich nicht nach Korinth gekommen bin.',
        24: 'Nicht als ob wir Herrschaft über euren Glauben ansprächen, sondern weil wir Mithelfer eurer Freude sind; denn ihr steht ja fest im Glauben.',
    },
    2: {
        1: 'Ich nahm mir aber vor, nicht abermals in Traurigkeit zu euch zu kommen.',
        2: 'Denn wenn ich euch betrübe, wer ist denn da, der mir Freude machen sollte, als die von mir betrübt worden sind; und dasselbige habe ich euch geschrieben, auf daß ich nicht, wenn ich käme, Traurigkeit haben müßte durch diejenigen, die mir Freude machen sollten; denn ich bin von euch allen überzeugt, daß meine Freude euer aller Freude ist.',
        3: 'Denn ich schrieb euch in großer Bedrängnis und Angst des Herzens unter vielen Tränen, nicht damit ihr solltet betrübt werden, sondern damit ihr die absonderliche Liebe erkennt, die ich zu euch habe.',
        4: 'So aber jemand Betrübnis angerichtet hat, der hat nicht mich betrübt, sondern teilweise',
        5: 'Es ist aber für solchen genug, daß er von der Mehrzahl so gestraft worden ist;',
        6: 'So daß ihr dagegen vielmehr ihm vergebt und ihn tröstet,',
        7: 'auf daß er nicht in allzu große Traurigkeit versinke.',
        8: 'Darum ermahne ich euch, ihm einen Beweis der Liebe zu geben.',
        9: 'Denn darum hatte ich euch geschrieben, um zu erkennen, ob ihr Probe haltet und in allem Folge leistet.',
        10: 'Dem ihr aber vergebt, dem vergebe auch ich; denn so ich etwas vergeben habe, so habe ich es um euretwillen vor Christus Angesicht vergeben;',
        11: 'Auf daß wir nicht vom Satan übervorteilt werden; denn uns ist nicht unbewußt, was er im Sinne hat.',
        12: 'Da ich aber gen Troas kam zur Verkündigung des Evangeliums von Christus, und obgleich mir eine Tür aufgetan war im Herrn, so hatte ich doch keine Ruhe in meinem Geist, weil ich meinen Bruder Titus nicht fand;',
        13: 'Sondern nahm Abschied von ihnen und fuhr nach Mazedonien ab.',
        14: 'Aber Gott sei gedankt, Der uns immer in Christus triumphieren läßt, und durch uns allerorten den Wohlgeruch der Erkenntnis desselben offenbart.',
        15: 'Denn wir sind ein Wohlgeruch Christi für Gott, beides, bei den Erlösten und den Verlorenen.',
        16: 'Diesen ein Geruch des Todes zum Tode, jenen ein Geruch des Lebens zum Leben, und wer ist hierzu tüchtig?',
        17: 'Denn wir fälschen nicht, wie so viele, das Wort Gottes, sondern reden in Christus als aus Lauterkeit und als aus Gott, vor Gott.',
    },
    3: {
        1: 'Heben wir denn abermals an, uns selbst zu empfehlen, oder bedürfen wir, wie etliche, der Empfehlungsbriefe an euch, oder Empfehlungsbriefe von euch?',
        2: 'Unser Brief seid ihr, in unsere Herzen geschrieben, der von aller Welt erkannt und gelesen wird;',
        3: 'Da es ist offenbar worden, daß ihr Christus Brief seid, von uns ausgefertigt, geschrieben nicht mit Tinte, sondern mit dem Geist des lebendigen Gottes, nicht auf steinerne Tafeln, sondern auf fleischerne Tafeln des Herzens.',
        4: 'Eine solche Zuversicht haben wir durch Christus auf Gott;',
        5: 'Nicht daß wir tüchtig wären von uns selber, etwas zu urteilen als aus uns selbst, sondern unsere Tüchtigkeit ist von Gott,',
        6: 'Der auch uns tüchtig gemacht hat zu Dienern eines neuen Bundes, nicht des Buchstabens, sondern des Geistes; denn der Buchstabe tötet, der Geist aber macht lebendig.',
        7: 'So aber der Dienst des Todes, mit Buchstaben in Steine gegraben, in Glanz erschien, so daß die Söhne Israels das Angesicht Moses wegen des Glanzes seines Angesichts, der doch vergänglich war, nicht anschauen konnten;',
        8: 'Wie sollte nicht der Dienst des Geistes noch viel mehr im Glanze sein?',
        9: 'Denn wenn der Dienst der Verdammnis Glanz ist, wieviel reicher ist an Glanz der Dienst der Gerechtigkeit!',
        10: 'Denn das in diesem Betreff in Glanz Gesetzte ist gegenüber dem überschwenglichen Glanze nicht im Glanz.',
        11: 'Denn wenn das Vergängliche schon im Glanz war, so ist noch vielmehr im Glanz das, so da bleibt.',
        12: 'Weil wir nun solche Hoffnung haben, sprechen wir uns mit aller Freimütigkeit aus,',
        13: 'Und tun nicht wie Moses, der eine Decke vor sein Angesicht nahm, auf daß die Söhne Israels nicht das Ende des Vergänglichen anschauen sollten.',
        14: 'Verstockt hingegen wurden ihre Gedanken; bis auf heute bleibt dieselbe Decke unaufgedeckt beim Lesen in dem alten Bunde, wird aber durch Christus weggetan.',
        15: 'Aber bis auf den heutigen Tag hängt, wenn im Moses gelesen wird, eine Decke vor ihrem Herzen.',
        16: 'Wenn es sich aber bekehrt zum Herrn, wird die Decke weggenommen.',
        17: 'Denn der Herr ist der Geist; wo aber der Geist des Herrn ist, da ist Freiheit.',
        18: 'Nun aber schauen wir alle mit aufgedecktem Angesicht wie im Spiegel die Herrlichkeit des Herrn, indem wir selbst von Herrlichkeit zu Herrlichkeit zu demselben Bilde umgestaltet werden, als vom Herrn, Welcher der Geist ist.',
    },
    4: {
        1: 'Weil wir nun solches Amt haben, nach der Barmherzigkeit, die uns ist zuteil geworden, werden wir nicht zaghaft;',
        2: 'Sondern haben von uns abgewiesen, was die Scham verbirgt, indem wir nicht wandeln in Schalkheit, noch das Wort Gottes verfälschen, sondern empfehlen uns durch das Offenbaren der Wahrheit an jedes Menschen Gewissen, im Angesichte Gottes.',
        3: 'Ist aber unser Evangelium auch noch verdeckt, so ist es verdeckt in denen, die verlorengehen.',
        4: 'Weil in diesen der Gott dieser Welt die Gedanken der Ungläubigen verblendet hat, so daß das Licht des Evangeliums von Christi Herrlichkeit, Welcher ist das Bild Gottes, nicht scheinen kann.',
        5: 'Denn wir predigen nicht uns selbst, sondern Jesus Christus, daß Er der Herr ist, wir aber eure Knechte sind um Jesus willen.',
        6: 'Denn der Gott, Der aus der Finsternis Licht hervorleuchten hieß, ist es, Der es leuchten ließ in unsere Herzen, damit die Erkenntnis der Herrlichkeit Gottes im Angesicht Jesus Christi leuchtete.',
        7: 'Wir haben aber diesen Schatz in irdischen Gefäßen, auf daß die Überschwenglichkeit der Kraft erscheine als von Gott, nicht von uns, ausgehend.',
        8: 'Auf alle Weise bedrängt, aber nicht geängstet; zaghaft, aber nicht verzagend; verfolgt, aber nicht verlassen;',
        9: 'Zu Boden geworfen, aber nicht umkommend:',
        10: 'So tragen wir allezeit Jesus Sterben an unserem Leibe umher, damit Jesus Leben an unserem Leibe geoffenbart werde.',
        11: 'Denn wir, die wir leben, werden um Jesus willen in den Tod gegeben, auf daß auch das Leben Jesus an unserem sterblichen Fleische offenbar werde.',
        12: 'Darum ist der Tod an uns wirksam, an euch aber das Leben.',
        13: 'Weil wir aber denselben Geist des Glaubens haben, gemäß dem, was geschrieben steht: ich glaube, darum rede ich, glauben auch wir, und darum reden wir auch,',
        14: 'Indem wir wissen, daß Er, Der den Herrn Jesus auferweckt hat, auch uns auferwecken und uns lebendig darstellen wird samt euch.',
        15: 'Denn alles geschieht um euretwillen, auf daß die Gnade durch die vielen die Danksagung zur Verherrlichung Gottes um so überschwenglicher mache.',
        16: 'Deshalb sind wir nicht zaghaft; sondern wenn auch unser äußerer Mensch aufgerieben wird, so wird doch der innere Mensch von Tag zu Tag erneuert.',
        17: 'Denn die augenblickliche, leichte Trübsal erwirkt für uns ein ewiges, überschwengliches Maß von Herrlichkeit.',
        18: 'Weil wir nicht auf das Sichtbare, sondern auf das Unsichtbare sehen. Denn das Sichtbare ist zeitlich, das Unsichtbare aber ist ewig.',
    },
    5: {
        1: 'Denn wir wissen, daß, wenn unsere irdische Zeltbehausung zerfällt, wir eine Behausung von Gott, eine nicht mit Händen gemachte, ewige Behausung, im Himmel haben.',
        2: 'Denn in diesem seufzen wir und sehnen uns, in die Behausung, die vom Himmel ist, einzuziehen,',
        3: 'So wir bekleidet sind und nicht nackt erfunden werden.',
        4: 'Denn solange wir in dieser Hütte sind, seufzen wir und fühlen uns beschwert, nicht als ob wir wollten ausgekleidet, sondern überkleidet werden, auf daß das Sterbliche vom Leben verschlungen werde.',
        5: 'Der uns für dasselbige vorbereitet hat, ist Gott, Der uns auch das Unterpfand des Geistes gegeben hat.',
        6: 'So sind wir nun allezeit getrost und wissen, daß, solange wir im Leibe daheim sind, wir noch fern vom Herrn in der Fremde wandern.',
        7: 'Denn wir wandeln im Glauben, nicht im Schauen.',
        8: 'Wir sind aber getrost, und haben Lust aus dem Körper auszuwanden und daheim zu sein bei dem Herrn.',
        9: 'Darum beeifern wir uns auch, ob wir daheim oder noch auf der Wanderung sind, Ihm wohlgefällig zu sein.',
        10: 'Denn wir müssen alle offenbar werden vor dem Richterstuhle Christus, auf daß ein jeglicher empfange, was er bei Leibes Leben getan, und je wie er gehandelt hat, es sei gut oder böse.',
        11: 'Weil wir denn wissen, daß der Herr zu fürchten ist, so überzeugen wir Menschen, vor Gott aber sind wir offenbar; ich hoffe aber, daß wir auch in euren Gewissen offenbar geworden sind.',
        12: 'Denn wir wollen uns nicht abermals vor euch loben, sondern euch Ursache geben, euch unser zu rühmen, auf daß ihr Grund habt wider die, so sich im Äußeren rühmen und nicht nach dem Herzen.',
        13: 'Denn gehen wir zu weit, so tun wir es für Gott; bescheiden wir uns, so tun wir es für euch.',
        14: 'Denn Christi Liebe hält uns in Schranken, weil wir also urteilen, daß, wenn einer für alle gestorben ist, so sind mithin alle gestorben.',
        15: 'Und Er ist für alle gestorben, auf daß die, so da leben, nicht mehr ihnen selbst leben, sondern Dem, Der für sie gestorben und auferstanden ist.',
        16: 'Darum kennen wir von nun an keinen mehr dem Fleische nach, wenn wir aber auch Christus dem Fleische nach gekannt haben, so kennen wir Ihn jetzt nicht mehr.',
        17: 'Wenn somit einer in Christus ist, so ist er eine neue Schöpfung; das Alte ist vergangen, siehe, alles ist neu geworden.',
        18: 'Alles aber ist von Gott, Der uns mit Sich durch Jesus Christus versöhnt und uns das Amt der Versöhnung verliehen hat.',
        19: 'Denn Gott war in Christus und versöhnte die Welt mit Ihm selber, und rechnete ihnen ihre Sünden nicht auf, und hat auf uns das Wort der Versöhnung gelegt.',
        20: 'So sind wir nun Botschafter an Christus Statt, indem Gott durch uns vermahnt; so bitten wir euch denn an Christus Statt: Lasset euch versöhnen mit Gott!',
        21: 'Denn Er hat Ihn, Der von keiner Sünde wußte, für uns zur Sünde gemacht, auf daß wir in Ihm die Gerechtigkeit Gottes würden.',
    },
    6: {
        1: 'Wir ermahnen euch nun als Mitarbeiter, daß ihr die Gnade Gottes nicht vergeblich empfanget.',
        2: 'Denn Er spricht: Ich habe dich zur Zeit der Gnade erhört, und dir am Tage des Heils geholfen. Seht, jetzt ist die Zeit der Gnade, jetzt ist der Tag des Heils.',
        3: 'Wir geben niemand Ärgernis, auf daß unser Amt kein Vorwurf treffe,',
        4: 'Sondern erweisen uns in allen Dingen als Diener Gottes, durch große Standhaftigkeit in Drangsalen, Ängsten und Nöten,',
        5: 'Unter Schlägen, in Gefängnissen, in Aufständen, in Mühseligkeiten, in Nachtwachen, in Fasten;',
        6: 'In Sittenreinheit, in Erkenntnis, in Langmut, in Freundlichkeit, im Heiligen Geist, in ungeheuchelter Liebe,',
        7: 'In wahrhaftiger Lehre, in der Kraft Gottes, durch die Waffen der Gerechtigkeit zu Schutz und Trutz;',
        8: 'Durch Ehre und Schande, durch bösen und durch guten Leumund, als Verführer und als Wahrhaftige,',
        9: 'Als Verkannte, und doch bekannt, als sterbend und siehe, wir leben, als Gezüchtige und doch nicht Ertötete,',
        10: 'Als Betrübte und die doch allezeit fröhlich sind, als Arme, die aber viele reich machen, als solche, die nichts haben und doch alles besitzen. -',
        11: 'Unser Mund, Korinther, hat sich gegen euch aufgetan; unser Herz ist erweitert.',
        12: 'Ihr habt in uns keinen engen Raum, habt aber engen Raum in euren Herzen. Zur Wiedervergeltung -',
        13: 'Ich rede zu euch, wie zu meinen Kindern - lasset es auch bei euch weiter werden.',
        14: 'Ziehet nicht am unrechten Joch mit den Ungläubigen; denn was hat die Gerechtigkeit gemein mit der Ungerechtigkeit? Welche Gemeinschaft ist zwischen dem Licht und der Finsternis?',
        15: 'Wie stimmt Christus mit Belial? Oder was hat der Gläubige zu schaffen mit dem Ungläubigen?',
        16: 'Wie kann der Tempel Gottes mit Götzenbildern in einen Vergleich kommen? Ihr seid ja der Tempel des lebendigen Gottes, wie Gott spricht: Ich will in ihnen wohnen und unter ihnen wandeln, und will ihr Gott sein und sie sollen Mein Volk sein.',
        17: 'Darum entfernt euch aus ihrer Mitte, und sondert euch ab von ihnen! spricht der Herr, und rührt das Unreine nicht an, so will Ich euch annehmen.',
        18: 'Und will euch Vater sein, und ihr sollt mir Söhne und Töchter sein, spricht der Herr, der Allmächtige.',
    },
    7: {
        1: 'Weil wir nun solche Verheißungen haben, Geliebte, wollen wir uns reinhalten von aller Befleckung des Fleisches und des Geistes, und in der Furcht Gottes die Heiligung zur Vollendung bringen.',
        2: 'Fasset uns wohl! wir haben niemand Unrecht getan, niemand beschädigt, niemand übervorteilt.',
        3: 'Dies sage ich nicht, um euch zu verurteilen; denn ich habe euch oben gesagt, daß wir euch in unseren Herzen tragen, und mit euch leben und sterben möchten.',
        4: 'Ich habe viel freudige Zuversicht zu euch, viel Rühmens über euch, bin voll des Trostes und über die Maßen mit Freuden erfüllt, trotz all unserer Drangsal.',
        5: 'Denn da wir nach Mazedonien kamen, hatte unser Fleisch keine Ruhe; alles drängte auf uns ein, von außen Kämpfe, von innen Anfechtungen.',
        6: 'Aber Gott, Der die Niedrigen aufrichtet, hat auch uns durch Titus Ankunft getröstet.',
        7: 'Aber nicht bloß durch seine Ankunft, sondern auch durch den Trost, der ihm zuteil ward über euch, indem er uns Meldung tat von eurem Verlangen, Bedauern und eurem Eifer für mich, so daß ich mich noch mehr freute.',
        8: 'Darum, wenn ich euch auch in dem Brief betrübt habe, so reut es mich jetzt doch nicht, wenn es mich auch gereut hätte; denn ich sehe, daß jener Brief euch nur eine Zeitlang betrübt hat.',
        9: 'Ich freue mich nun, nicht, daß ihr betrübt worden, sondern daß ihr betrübt worden seid zur Sinnesänderung; denn ihr seid betrübt worden nach dem Willen Gottes, auf daß ihr von uns aus ja in keinem Stücke Schaden nähmet.',
        10: 'Denn die Betrübnis nach Gottes Willen wirkt Reue zur Seligkeit, die niemand zu bereuen hat, die Betrübnis der Welt aber bewirkt den Tod.',
        11: 'Siehe, eben das, daß ihr nach dem Willen Gottes betrübt worden seid, welchen Eifer hat es in euch angeregt, ja Entschuldigung, ja Unwillen, Furcht, Verlangen, Eifer, Ahndung! Ihr habt euch in allen Stücken erwiesen, daß ihr rein seid in der Sache.',
        12: 'Darum, wenn ich euch auch geschrieben habe, so ist es doch nicht geschehen wegen dessen, der unrecht getan, noch wegen dessen, dem Unrecht getan worden ist, sondern deswegen, daß unser Eifer für euch bei euch vor Gott geoffenbart würde.',
        13: 'Darum sind wir über eurer Tröstung getröstet worden, unsere Freude aber ward noch ungemein erhöht über der Freude des Titus, daß sein Gemüt an euch allen erquickt worden ist;',
        14: 'Denn ich bin in dem, was ich gegen ihn von euch gerühmt habe, nicht zuschanden geworden, vielmehr ist alles, was ich in Wahrheit zu euch geredet habe, somit auch unser Rühmen bei Titus, Wahrheit geworden.',
        15: 'Und sein Innerstes ist euch noch mehr zugetan, wenn er euer aller Gehorsam gedenkt, wie ihr ihn mit Furcht und Zittern aufgenommen habt.',
        16: 'Ich freue mich, daß ich mich in allem auf euch verlassen kann.',
    },
    8: {
        1: 'Ich tue euch, Brüder, kund die Gnade Gottes, die sich in den Gemeinden Mazedoniens erwiesen hat,',
        2: 'Daß in viel Drangsalsprüfung die Überschwenglichkeit ihrer Freude und die tief hinabreichende Armut sich überschwenglich erwiesen in reicher Mildtätigkeit;',
        3: 'Denn nach Vermögen [das bezeuge ich], ja über Vermögen waren sie willfährig.',
        4: 'Und erbaten sich auf das angelegentlichste von uns die Gunst der Teilnahme an der Beisteuer für die Heiligen;',
        5: 'Ja, über unser Erwarten ergaben sie sich vor allem dem Herrn und uns nach dem Willen Gottes, zum Dienste hin;',
        6: 'So daß wir Titus baten, daß er, wie er schon angefangen, auch unter euch diese Liebesgabe ausrichtete.',
        7: 'Aber wie ihr in allen Stücken reich seid im Glauben und in der Lehre und Erkenntnis, und in jeglichem Eifer und auch in eurer Liebe gegen uns, so seid nun auch überschwenglich in diesem Liebeswerk.',
        8: 'Ich sage dies nicht, als ob ich gebieten wollte, sondern weil andere so eifrig sich bewiesen, möchte ich die Aufrichtigkeit auch eurer Liebe prüfen.',
        9: 'Ihr kennt ja die Gnade unseres Herrn Jesus Christus, Der, ob Er gleich reich war, um euretwillen Armut litt, auf daß ihr durch Seine Armut reich würdet und ich gebe euch hierin meinen Rat.',
        10: 'Denn dies frommt euch, die ihr nicht allein im Tun, sondern auch im Gernetun seit vorigem Jahr einen Anfang gemacht habt.',
        11: 'Nun aber vollbringt auch das Tun, daß ihr, so wie eine Geneigtheit des Wollens da war, so auch es nach Vermögen vollbringt.',
        12: 'Denn so die Geneigtheit vorhanden ist, je nach Vermögen zu tun, so ist sie Gott angenehm, nicht nach dem sie nicht vermag.',
        13: 'Nicht, daß ihr, damit es anderen leichter würde, Mangel littet, sondern daß eine Gleichheit wäre;',
        14: 'So diene denn zur Zeit euer Überfluß ihrem Mangel, auf daß auch ihr Überfluß eurem Mangel diene, und so eine Gleichheit eintrete.',
        15: 'Wie denn geschrieben steht: Der viel gesammelt, hatte nicht mehr, und der wenig gesammelt, hatte nicht weniger.',
        16: 'Gott aber sei Dank, Der eben solchen Fleiß für euch dem Titus in das Herz gegeben hat;',
        17: 'Denn er folgte nicht nur meiner Aufforderung, sondern ging noch mit mehr Eifer aus freien Stücken zu euch ab.',
        18: 'Wir haben ihm aber einen Bruder beigegeben, der das Lob hat am Evangelium bei allen Gemeinden;',
        19: 'Nicht allein aber das, sondern er ist auch von den Gemeinden zu unserem Gefährten in diesem Liebeswerk aufgestellt, das von uns zur Ehre des Herrn und zum Beweis unseres guten Willens ausgerichtet wird.',
        20: 'Wir sahen darauf, daß uns bei solcher reichen Beisteuer, die von uns betrieben wird, nicht jemand Übles nachrede.',
        21: 'Und haben Vorsorge getroffen, daß es redlich zugehe, nicht allein vor dem Herrn, sondern auch vor Menschen.',
        22: 'Auch haben wir mit ihnen noch unseren Bruder gesandt, dessen Eifer wir oft in vielen Stücken bewährt gefunden, und der bei dem großen Zutrauen zu euch noch viel eifriger geworden ist;',
        23: 'Sei es, daß ich für Titus rede, so ist er mein Genosse und Mitarbeiter bei euch; sei es, daß es Brüder von uns sind, Abgeordnete der Gemeinden, Christus eine Ehre.',
        24: 'Gebt an ihnen nun Beweise eurer Liebe und bestätigt Angesichts der Gemeinden unser rühmendes Zeugnis über euch.',
    },
    9: {
        1: 'Denn von solcher Beisteuer für die Heiligen brauche ich nicht weiter an euch zu schreiben.',
        2: 'Denn ich kenne eure Bereitwilligkeit, deren ich vor den Mazedoniern rühmend gedenke, daß Achaja schon voriges Jahr dazu Vorbereitung getroffen hat; und euer Eifer hat allgemein aufgemuntert.',
        3: 'Ich habe die Brüder gesandt, auf daß mein Rühmen von euch in diesem Stück nicht zunichte werde.',
        4: 'Auf daß, wie ich sagte, ihr vorbereitet wäret, und wir [ich will nicht sagen ihr], wenn Mazedonier mit mir kämen und euch unvorbereitet fänden, mit solch zuversichtlichem Rühmen zuschanden würden.',
        5: 'Ich habe es daher für nötig erachtet, die Brüder zu ersuchen, daß sie zu euch voranzögen, um euren vorher verheißenen Segen in Empfang zu nehmen und ihn bereit zu halten, auf daß es so als ein Segen und nicht als eine Erpressung angesehen werde.',
        6: 'Da gilt der Spruch: Wer da kärglich sät, der wird kärglich ernten, und wer da sät im Segen, der wird auch ernten im Segen.',
        7: 'Ein jeglicher gebe, wie ihn das Herz treibt, nicht mit Widerwillen oder als Nötigung; denn einen fröhlichen Geber hat Gott lieb.',
        8: 'Gott ist aber mächtig, euch allerlei Gnade in reichem Maße zu erteilen, und daß ihr allerwege in allen Dingen volle Genüge habt und reich seiet zu allerlei gutem Werke.',
        9: 'Wie geschrieben steht: Er hat ausgesät und den Armen gegeben; Seine Gerechtigkeit bleibt in Ewigkeit.',
        10: 'Der aber Samen reicht dem, der da sät, und Brot zur Speise, wird auch eure Saat mehren und die Früchte eurer Gerechtigkeit gedeihen lassen,',
        11: 'Daß ihr reich werdet in allen Dingen für jegliches Werk der Herzenseinfalt, die durch uns Dank gegen Gott bewirkt.',
        12: 'Denn die Handreichung dieser Beisteuer hilft nicht nur den Bedürfnissen der Heiligen ab, sondern ist auch überschwenglich durch viele Danksagungen gegen Gott,',
        13: 'Die für diese Beweise der Dienstleistung Gott preisen wegen des Gehorsams gegen das Evangelium von Christus, das ihr bekennt, und wegen eurer herzlichen Mildtätigkeit gegen sie und gegen alle.',
        14: 'Indem auch sie mit Gebet für euch sich nach euch sehnen.',
        15: 'Gott aber sei Dank für Seine unaussprechliche Gabe.',
    },
    10: {
        1: 'Ich Paulus aber, der ich persönlich unter euch gering, abwesend aber dreist bin, ermahne euch bei Christus Sanftmut und Seiner Milde.',
        2: 'Ich bitte euch, daß ich nicht gegenwärtig dreist auftreten müsse mit der Zuversichtlichkeit, mit der ich dreist zu sein erachte gegen gewisse Leute, die von uns glauben, daß wir nach fleischlicher Weise wandelten.',
        3: 'Denn obgleich wir im Fleische wandeln, so streiten wir doch nicht nach dem Fleische.',
        4: 'Denn die Waffen unseres Kampfes sind nicht fleischlich, sondern mächtig für Gott zur Niederreißung von Bollwerken.',
        5: 'Die wir Anschläge und alles Hohe, das sich wider die Erkenntnis Gottes erhebt, zerstören, und alles Denken unter Christus Gehorsam gefangennehmen,',
        6: 'Und bereit sind, allen Ungehorsam zu strafen, wenn euer Gehorsam sich durch die Tat bewährt.',
        7: 'Seht ihr auf das Äußere? Traut jemand sich zu, daß er Christus angehöre, der denke wieder von selber, daß, wie er Christus angehört, also auch wir ihm angehören.',
        8: 'Und wenn ich noch etwas weiter mich rühmte von unserer Gewalt, die uns der Herr gegeben hat zu eurer Erbauung, und nicht zu eurer Zerstörung, so werde ich nicht zuschanden werden:',
        9: 'Auf daß ich nicht scheine, euch durch die Briefe schrecken zu wollen;',
        10: 'Denn die Briefe, sagt einer, sind gewichtig und nachdrücklich, aber die leibliche Gegenwart ist schwach und die Rede kraftlos.',
        11: 'Ein solcher denke, daß, wie wir abwesend in den Briefen mit Worten sind, so dürften wir auch wohl anwesend mit der Tat sein.',
        12: 'Denn wir unterfangen uns nicht, uns denen, die sich selbst loben, beizuzählen oder zu vergleichen; aber weil sie sich an sich selbst messen und sich allein mit sich vergleichen, tun sie unverständig.',
        13: 'Wir aber wollen uns nicht ins Ungemessene rühmen, sondern nach dem Maß des Bereichs, das uns Gott zugemessen hat, auch bis zu euch reichen.',
        14: 'Denn nicht, als wären wir solche, die nicht zu euch hinreichen, überstrecken wir uns selbst; denn wir sind bis zu euch gelangt mit dem Evangelium von Christus;',
        15: 'Und wir rühmen uns nicht im Übermaß fremder Arbeit, sind aber der Hoffnung, daß wir, wenn euer Glaube zunimmt, nach unserer Richtschnur an euch noch weiter gelangen,',
        16: 'Und auch über euch hinaus das Evangelium predigen und uns nicht innerhalb eines fremden Gebietes dessen rühmen, das schon fertig ist.',
        17: 'Wer sich aber rühmt, der rühme sich des Herrn.',
        18: 'Denn darum, daß einer sich selbst lobt, ist er noch nicht bewährt, sondern daß ihn der Herr lobt.',
    },
    11: {
        1: 'Ich wollte, ihr hieltet mir ein wenig Torheit zugut, und ihr tut es wohl auch.',
        2: 'Denn ich eifere um euch mit dem Eifer Gottes, denn ich habe euch einem Manne verlobt, um eine reine Jungfrau Christus zuzuführen.',
        3: 'Ich fürchte aber, daß, wie die Schlange Eva durch ihre List verführte, auch euer Sinn berückt und von dem einfältigen Glauben an Christus abgewendet werde.',
        4: 'Denn wenn der Nächste, so da kommt, einen anderen Jesus predigte, als wir gepredigt haben, oder ihr einen anderen Geist empfinget, den ihr von uns nicht empfangen habt, oder ein anderes Evangelium, das ihr nicht angenommen hattet, so würdet ihr es euch recht schön gefallen lassen.',
        5: 'Denn ich erachte, ich stehe in nichts zurück hinter den hohen Aposteln:',
        6: 'Denn wenn ich auch ein Laie bin im Reden, so bin ich es doch nicht in der Erkenntnis; vielmehr sind wir in allem vor allen bei euch offenbar geworden.',
        7: 'Oder habe ich Unrecht getan, daß ich mich selbst erniedrigte, auf daß ihr erhöht würdet, daß ich euch unentgeltlich das Evangelium Gottes verkündigt habe?',
        8: 'Auch habe ich andere Gemeinden beraubt, indem ich Sold von ihnen genommen, daß ich euch dienete.',
        9: 'Und während ich bei euch war und Mangel litt, bin ich niemand zur Last gefallen; denn meinem Mangel halfen die Brüder ab, die aus Mazedonien kamen, und in allen Stücken bin ich euch nicht lästig geworden, und werde es auch in Zukunft so halten.',
        10: 'So wahr die Wahrheit von Christus in mir ist, soll mir dieser Ruhm nicht verwehrt werden, solange ich in den Landen Achajas bin.',
        11: 'Warum? Weil ich euch nicht liebe? Gott weiß es.',
        12: 'Was ich aber tue, will ich auch ferner tun, daß ich denen den Anlaß abschneide, die einen Anlaß suchen, auf daß sie in dem, dessen sie sich rühmen, erfunden werden gleich wie wir.',
        13: 'Denn diese Afterapostel sind trügliche Arbeiter, welche die Gestalt von Christus Aposteln annehmen.',
        14: 'Auch ist es kein Wunder, denn der Satan selbst gestaltet sich in einen Engel des Lichtes um.',
        15: 'Darum ist es nun nichts Großes, wenn auch seine Diener sich in Diener der Gerechtigkeit umgestalten, deren Ende auch ihren Werken entsprechen wird.',
        16: 'Ich sage abermals: Niemand halte mich für unverständig; wenn aber doch, so nehmt mich als einen solchen Unverständigen an, daß auch ich mich ein wenig rühmen darf.',
        17: 'Was ich jetzt rede, rede ich nicht als aus dem Herrn, sondern wie im Unverstand bei diesem Gegenstande des Rühmens.',
        18: 'Weil viele sich rühmen nach dem Fleische, will auch ich mich rühmen.',
        19: 'Denn ihr hört ja gerne Unverständige an, weil ihr so verständig seid.',
        20: 'Ihr lasset euch ja gefallen, wenn einer euch zu Sklaven macht, wenn einer euch aufzehrt, euch fängt, sich erhebt, euch ins Angesicht schlägt.',
        21: 'Ich sage das zur Schmach, wie auch, daß wir darin schwach gewesen sind; worin aber einer kühn ist - ich spreche wieder im Unverstand - da bin auch ich kühn.',
        22: 'Hebräer sind sie? Auch ich. Israeliten sind sie? Auch ich. Abrahams Samen sind sie? Auch ich.',
        23: 'Christi Diener sind sie? - ich rede wieder im Unverstand: - Ich noch mehr. Ich bin in mehr Mühsalen gewesen, in Streichen über die Maßen, in mehr Kerkern, oft in Todesnöten.',
        24: 'Von den Juden habe ich fünfmal vierzig Streiche weniger einen empfangen.',
        25: 'Bin dreimal gestäupt, einmal gesteinigt worden, habe dreimal Schiffbruch gelitten, habe einen Tag und eine Nacht in Meerestiefen zugebracht,',
        26: 'Bin oft auf Reisen gewesen, in Gefahren auf Flüssen, in Gefahren vor Mördern, in Gefahren unter Stammgenossen, in Gefahren unter Heiden, in Gefahren in der Stadt, in Gefahren in der Wüste, in Gefahren auf dem Meer, in Gefahren unter falschen Brüdern;',
        27: 'In Mühsal und Elend, in häufigen Nachtwachen, in Hunger und Durst, oftmals in Fasten, in Frost und Blöße;',
        28: 'Ohne was sich sonst zuträgt, der tägliche Überlauf, die Sorge für alle die Gemeinden.',
        29: 'Wer ist schwach, daß ich nicht schwach werden dürfte? Wer wird geärgert, daß ich nicht entbrennen sollte?',
        30: 'So ich mich je rühmen sollte, will ich mich meiner Schwachheit rühmen.',
        31: 'Gott und der Vater unseres Herrn Jesus Christus, Der sei hochgelobt in Ewigkeit, weiß, daß ich nicht lüge.',
        32: 'In Damaskus ließ der Präfekt des Königs Aretas die Stadt der Damasker schließen und wollte meiner habhaft werden;',
        33: 'Und ich ward in einem Korb aus einem Fenster an der Stadtmauer hinabgelassen und entrann seinen Händen.',
    },
    12: {
        1: 'Das Rühmen ist mir ja nichts nütze; doch will ich auf Gesichte und Offenbarungen des Herrn kommen.',
        2: 'Ich weiß einen Menschen in Christus, der vor vierzehn Jahren - ist er im Leibe gewesen, so weiß ich es nicht, ist er außer dem Leibe gewesen, so weiß ich es auch nicht; Gott weiß es -',
        3: 'Bis in den dritten Himmel entrückt ward,',
        4: 'Und dort unaussprechliche Worte hörte, die ein Mensch nicht sagen kann.',
        5: 'Über solchem will ich mich rühmen; für mich selbst aber will ich mich nicht rühmen, es sei denn meiner Schwachheiten.',
        6: 'Denn so ich mich rühmen wollte, wäre ich darum noch nicht unverständig, denn ich würde die Wahrheit reden; ich enthalte mich aber dessen, damit nicht jemand mich höher achte, als er an mir sieht und von mir hört.',
        7: 'Und auf daß ich mich nicht der überschwenglichen Offenbarungen überheben möchte, ward mir ein Pfahl ins Fleisch gegeben, ein Satansengel, daß er mich mit Fäusten schlage, auf daß ich mich nicht überhebe.',
        8: 'Darüber habe ich dreimal zum Herrn gefleht, daß er von mir wiche.',
        9: 'Und Er hat zu mir gesagt: Laß dir an Meiner Gnade genügen; denn Meine Kraft ist in den Schwachen mächtig. Darum will ich mich am liebsten rühmen der Schwachheiten, auf daß Christus Kraft in mir wohne.',
        10: 'Deshalb bin ich guten Mutes in Schwachheiten, in Schmachen, in Nöten, in Verfolgungen, in Bedrängnissen um Christus willen; denn wenn ich schwach bin, dann bin ich stark.',
        11: 'Ich bin unverständig geworden über meinem Rühmen; ihr habt mich dazu genötigt. Denn ich sollte von euch gelobt werden, weil ich in nichts den hohen Aposteln nachstehe, wenn ich gleich nichts bin.',
        12: 'Denn die Zeichen des Apostels sind unter euch geschehen, mit Erduldung von allerlei Leiden, mit Zeichen und Wundern und Krafterweisungen.',
        13: 'Denn worin seid ihr den anderen Gemeinden nachgestanden, es sei denn darin, daß ich selbst euch nicht zur Last gefallen bin? Haltet mir dieses Unrecht zugute.',
        14: 'Siehe, ich bin bereit, ein drittes Mal zu euch zu kommen, und werde euch nicht beschwerlich fallen; denn es ist mir nicht um das Eurige, sondern um euch zu tun; denn nicht die Kinder haben für die Eltern, sondern die Eltern für die Kinder Schätze zu sammeln.',
        15: 'Ich aber will recht gern Opfer bringen, und ein Opfer werden für eure Seelen; wenn ich auch, der ich euch überschwenglich liebe, weniger geliebt werde.',
        16: 'Aber ich habe euch vielleicht keine Kosten gemacht, bin dagegen schlau genug gewesen, euch mit Hinterlist zu fangen.',
        17: 'Habe ich durch einen von denen, die ich zu euch sandte, euch übervorteilt?',
        18: 'Ich forderte Titus auf und sandte den Bruder mit ihm - hat euch etwa Titus übervorteilt, sind wir nicht in einem Geiste gewandelt, nicht in die gleichen Fußstapfen getreten?',
        19: 'Glaubt ihr abermals, daß wir gegen euch uns verantworten wollen? Vor Gott in Christus reden wir das alles, Geliebte, zu eurer Erbauung.',
        20: 'Denn ich fürchte, daß ich, wenn ich komme, euch nicht so finden möchte, wie ich wünschte, und ich von euch nicht so erfunden werde, wie ihr mich wünschet; daß Hader, Eifersucht, Ärgernisse, Streitigkeiten, Verleumdungen, Ohrenbläsereien, Aufgeblasenheiten und Verwirrungen stattgegriffen haben;',
        21: 'Daß, wenn ich abermals komme, mein Gott mich bei euch demütige, und ich Leid tragen müsse über viele, die zuvor gesündigt und nicht Buße getan haben für die Unreinheit, Hurerei und Schwelgerei, deren sie sich schuldig machten.',
    },
    13: {
        1: 'Ich komme nun zum dritten Mal zu euch, und auf zweier oder dreier Zeugen Munde soll jegliche Sache bestehen!',
        2: 'Ich habe es vorhergesagt und wiederhole es [als wäre ich gegenwärtig] noch einmal [und vorerst abwesend,] für die, so vorher gesündigt und für alle anderen, daß, wenn ich wiederkomme, ich nicht schonen will.',
        3: 'Weil ihr eine Bewährung des in mir redenden Christus verlangt, Der an euch nicht unkräftig, sondern mächtig ist.',
        4: 'Denn wenn Er auch in der Schwachheit gekreuzigt wurde, so lebt Er doch in der Kraft Gottes, so sind wir nämlich schwach in Ihm, werden aber vermöge der Kraft Gottes mit Ihm für euch leben.',
        5: 'Prüfet euch selbst, ob ihr im Glauben seid! Bewährt euch selbst! oder erkennt ihr nicht an euch selbst, daß Jesus Christus in euch ist, wofern ihr nicht etwa in der Probe nicht besteht?',
        6: 'Ich hoffe aber, daß ihr erkennen werdet, daß wir nicht unbewährt sind.',
        7: 'Ich bete aber zu Gott, daß Er euch nichts Unrechtes tun lasse, nicht damit wir als bewährt erscheinen, sondern damit ihr das Rechte tut, und wir vielmehr wie unbewährt seien.',
        8: 'Denn wir können nichts wider die Wahrheit, sondern für die Wahrheit.',
        9: 'Wir freuen uns ja, wenn wir die Schwachen sind, ihr aber stark seid; dafür beten wir sogar, daß ihr vollkommen seiet.',
        10: 'Darum schreibe ich dies noch abwesend, auf daß ich nicht anwesend scharf verfahren müßte, nach der Gewalt, die mir der Herr verliehen hat, zur Erbauung und nicht zur Zerstörung.',
        11: 'Im übrigen, Brüder, freut euch, werdet vollkommen, laßt euch ermahnen, seid einträchtig, haltet Frieden, so wird der Gott der Liebe und des Friedens mit euch sein.',
        12: 'Grüßet einander mit dem heiligen Kuß, es grüßen euch alle Heiligen.',
        13: 'Die Gnade des Herrn Jesus Christus, und die Liebe Gottes, und die Gemeinschaft des Heiligen Geistes sei mit euch allen! Amen.',
    },
}
